		};
	};

	function fetchMicroLevelApplicants(fromDateString, toDateString) {

	$("#dynamic-table").dataTable( {
        "bProcessing": true,
        "bServerSide": true,
        "sort": "position",
        //bStateSave variable you can use to save state on client cookies: set value "true" 
        "bStateSave": false,
        //Default: Page display length
        "iDisplayLength": 10,
        //We will use below variable to track page number on server side(For more information visit: http://legacy.datatables.net/usage/options#iDisplayStart)
        "iDisplayStart": 0,

        "fnDrawCallback": function () {

        	angular.element('#StartOrFinishSpinnerId').scope().startOrStopSpinner(false);

        	//Get page numer on client. Please note: number start from 0 So
            //for the first page you will see 0 second page 1 third page 2...
            //Un-comment below alert to see page number
        	//alert("Current page number: "+this.fnPagingInfo().iPage);    
        }, 
        "fnCreatedRow" : function (nRow, aData, iDataIndex) {
    		$('td:eq(0)', nRow).addClass( 'customFont' );
    		$('td:eq(1)', nRow).addClass( 'customFont' );
    		$('td:eq(2)', nRow).addClass( 'customFont' );
    		$('td:eq(3)', nRow).addClass( 'customFont' );
    		$('td:eq(4)', nRow).addClass( 'customFont' );

    		$('td:eq(5)', nRow).addClass( 'customFont' );
    		$('td:eq(6)', nRow).addClass( 'customFont' );
    		$('td:eq(7)', nRow).addClass( 'customFont' );
    		$('td:eq(8)', nRow).addClass( 'customFont' );
    		$('td:eq(9)', nRow).addClass( 'customFont' );

    		$('td:eq(10)', nRow).addClass( 'customFont' );
    		$('td:eq(11)', nRow).addClass( 'customFont' );
    		$('td:eq(12)', nRow).addClass( 'customFont' );
    		$('td:eq(13)', nRow).addClass( 'customFont' );
    		$('td:eq(14)', nRow).addClass( 'customFont' );

    		$('td:eq(15)', nRow).addClass( 'customFont' );
    		$('td:eq(16)', nRow).addClass( 'customFont' );
    		$('td:eq(17)', nRow).addClass( 'customFont' );
      },
        "sAjaxSource": "fetchmicrolevelapplicants/"+fromDateString+"/"+toDateString,
        "aoColumns": [
            { "mData": "uamNumber", "bSortable": false  },
            { "mData": "uamDate", "bSortable": false },
            { "mData": "ownerOrPartnerName", "bSortable": false  },
            { "mData": "unitName", "bSortable": false },
            { "mData": "unitAddress", "bSortable": false },

            { "mData": "category", "bSortable": false  },
            { "mData": "gender", "bSortable": false },
            { "mData": "isHandicappedString", "bSortable": false  },
            { "mData": "enterpriseType", "bSortable": false },
            { "mData": null, 
            	mRender: function (data, type, row) {
            		var moc=row.nicCode;
            		if(null== moc){
            			moc="";
            		}
            		return moc; 
	              }, "bSortable": false },
            { "mData": "productionDate", "bSortable": false  },
            { "mData": null, mRender: function (data, type, row) {
        		var moc=row.prodClassification;
        		if(null== moc){
        			moc="";
        		}
        		return moc; 
              }, "bSortable": false },
            { "mData": null, mRender: function (data, type, row) {
        		var moc=row.prodName;
        		if(null== moc){
        			moc="";
        		}
        		return moc; 
              }, "bSortable": false  },
            { "mData": "prodCapacity", "bSortable": false },
            { "mData": "landOrHouseInvestment", "bSortable": false },

            { "mData": "plantOrMachineryInvestment", "bSortable": false  },
            { "mData": "totalEmployments", "bSortable": false },
            { "mData": "localEmployments", "bSortable": false  },
        ],

    } );

}

